//! The extension module `kibends._core`: a thin pyo3 binding of
//! `kibends-core`, converting between Python values and the core's types.
//! Its stub, `src/kibends/_core.pyi`, is generated by the `stub_gen` binary
//! from the stub information `stub_info` gathers.

mod arrays;
mod build;
mod burst;
mod energy;
mod field;
mod fields;
mod helpers;
mod optimize;
mod problem;
mod testing;
mod vias;

use std::path::Path;

use pyo3::prelude::*;
use pyo3_stub_gen::StubInfo;
use pyo3_stub_gen::derive::gen_stub_pyfunction;
use pyo3_stub_gen::runtime::PyModuleTypeAliasExt;

pyo3_stub_gen::type_alias!(
    "kibends._core",
    Field = field::Obstacles
        | fields::ChainField
        | fields::CompositeField
        | testing::FreeSpace
        | testing::Disc
        | testing::Box
        | testing::Walls
        | testing::MisleadingWalls
        | testing::Union
        | testing::ReachIgnored
        | testing::NanField,
    "A field implemented here, which a `CompositeField` can join."
);

/// The version of the extension module, which is kibends' version.
#[gen_stub_pyfunction]
#[pyfunction]
fn version() -> &'static str {
    kibends_core::VERSION
}

#[pymodule]
fn _core(m: &Bound<'_, PyModule>) -> PyResult<()> {
    m.add_function(wrap_pyfunction!(version, m)?)?;
    field::register(m)?;
    build::register(m)?;
    burst::register(m)?;
    fields::register(m)?;
    energy::register(m)?;
    helpers::register(m)?;
    optimize::register(m)?;
    problem::register(m)?;
    testing::register(m)?;
    vias::register(m)?;
    m.add_type_alias::<Field>()?;
    Ok(())
}

/// The module's stub information, read with the `[tool.maturin]` settings of
/// the project's `pyproject.toml`, two directories above this crate.
pub fn stub_info() -> pyo3_stub_gen::Result<StubInfo> {
    let manifest_dir = Path::new(env!("CARGO_MANIFEST_DIR"));
    StubInfo::from_pyproject_toml(manifest_dir.join("../../pyproject.toml"))
}
